select json_build_object('public_schema_acl',(select nspacl::text from pg_namespace where nspname='public'),'public_schema_owner',(select pg_get_userbyid(nspowner) from pg_namespace where nspname='public'),'column_level_acls',(select coalesce(json_agg(json_build_object('table',c.relname,'column',a.attname,'acl',a.attacl::text)),'[]'::json) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and a.attacl is not null),'default_privileges',(select coalesce(json_agg(json_build_object('role',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,'(all)'),'object_type',d.defaclobjtype,'acl',d.defaclacl::text) order by 1,2,3),'[]'::json) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace)) as data;
